mapper.select:
SELECT id, str_id, turbidity_value, unit, measured_at
FROM water_quality_data
WHERE source_id = #{sourceId}
ORDER BY measured_at DESC
    LIMIT #{limit}

SELECT r.str_id, r.keywords, r.generated_at FROM analysis_reports r JOIN water_sources s ON r.source_id = s.id WHERE s.user_id = #{userId}
AND r.str_id < #{lastStrId}
ORDER BY r.str_id DESC LIMIT #{pageSize}

mapper.update:
UPDATE analysis_reports r
    JOIN water_sources s ON r.source_id = s.id
    SET r.is_published = #{isPublished}
WHERE r.str_id = #{reportStrId}
  AND s.user_id = #{userId}

mapper.delete:
DELETE r
FROM analysis_reports r
JOIN water_sources s ON r.source_id = s.id
WHERE r.str_id = #{reportStrId}
AND s.user_id = #{userId}

mapper.select:
SELECT r.str_id, r.keywords, r.generated_at FROM analysis_reports r JOIN water_sources s ON r.source_id = s.id WHERE s.str_id = #{sourceStrId} AND s.user_id = #{userId}
AND r.str_id < #{lastStrId}
ORDER BY r.str_id DESC LIMIT #{pageSize}
